      "stem": "股票未公開發行之甲股份有限公司實收資本額為新臺幣 1 億元，轉投資乙股份有限公司 5,000 萬元，若甲股份有限公司章程對轉投資未有規定，依公司法，該轉投資行為之效力為何？",
