      "sourceId": "investment-05",
      "number": 8,
      "stem": "下列有關資本資產定價模式 (CAPM)的風險與報酬敘述，何者正確？Ⅰ.對報酬率變異數較大的股票，投資人會要求較高的期望報酬率； Ⅱ.報酬率對市場投資組合變動非常敏感的股票，投資人會要求較高的期望報酬率； Ⅲ.單一股票對充分分散投資組合風險的貢獻程度，取決於該股票的市場風險；Ⅳ.β 值小於零的投資，其期望報酬率低於無風險利率",
