      "stem": "如果股價是依循隨機漫步(Random Walk)，下列敘述何者為真？Ⅰ.前後期的股價並無關係；Ⅱ.前後期的股價變動並無關係；Ⅲ.股價變動在正常的長期價格做上下震盪；Ⅳ.股價的歷史資料無法用來預估投資人的未來報酬",
