      "stem": "某投資人以每股 100 元，融券賣出某上市股票五千股，融券保證金成數為九成。若在兩週後，該投資人以每股 73 元，融券買進該上市股票五千股。在假設證券商手續費率、證券交易稅率、融券手續費率與融券利率為 0%時，試計算實現報酬率為多少？",
