      "stem": "依證券投資信託基金管理辦法之規定，所稱得同時投資於股票、債券（包含其他固定收益證券）、基金受益憑證、不動產投資信託基金受益證券及經金融監督管理委員會核准得投資項目等資產種類，且投資於前開任一資產種類之總金額不得超過本基金淨資產價值之百分之七十者，係指下列何種基金？",
