      "subject": "accounting",
      "sourceId": "accounting-03",
      "number": 20,
      "stem": "下列何者屬於會計政策變動？甲.不動產、廠房及設備之折舊方法自直線法變更為年數合計法；乙.投資性不動產之後續衡量自成本模式變更為公允價值模式；丙.存貨成本流動自先進先出法變更為加權平均法；丁.不動產、廠房及設備之耐用年數自 5 年變更為 4 年",
