      "subject": "accounting",
      "sourceId": "accounting-02",
      "number": 24,
      "stem": "甲公司存貨採用永續盤存制，成本流動假設採用先進先出法。於 X2 年度結帳前發現 X1 年底的存貨金額高估$3,200，X1 年底的存貨已於 X2 年度出售，則甲公司 X2 年之更正分錄應包括：",
