      "stem": "甲公司於 X3 年的稅後淨利為$39,600，加權平均流通在外之普通股數為 6,000 股，所得稅率為 40%。甲公司其他相關資訊如下：(1)X3 年初發行認股權，共可認購 9,000 股普通股，執行價為$90，全年流通在外，且普通股全年平均股價為$150；(2)X3 年初以面額發行 9％之可轉換累積特別股 8,000 股，每股面額$10，每 1 股特別股可轉換為 1 股普通股。該特別股全年流通在外且無轉換；(3)X3 年 5 月 1 日發行面額$600,000，票面利率 6%之可轉換公司債，轉換價格為每股$100。該公司債以$660,000 發行，其中負債組成部分為$600,000 ，權益組成部分為$60,000。該公司債全年流通在外且無轉換。試問：甲公司 X3 年之稀釋每股盈餘金額為多少元？",
