      "sourceId": "law-18",
      "number": 33,
      "stem": "依據中華民國證券投資信託暨顧問商業同業公會證券投資顧問事業從業人員行為準則，公司應就全權委託投資業務投資經理人及依其權責執行全權委託帳戶投資決策或執行公司有關投資交易行為者之辦公處所訂定資訊及通訊設備使用管理規範，其內容應包括，非公司提供之資訊及通訊設備，應事前經公司許可始得使用並應於台股交易時段內集中保管。公司得建立集中保管時須接收訊息之替代作法，且公司因替代作法提供電話機為通訊管道者，應於台股交易時段錄音且其錄音保存期限應至少為幾年？",
