      "year": 114,
      "session": 3,
      "subject": "accounting",
      "sourceId": "accounting-03",
      "number": 11,
      "stem": "某公司於X1 年初以$120,000購入一專利權，經評估其經濟效益年限為6 年，其法定有效年限為 12 年。X3 年初此專利權蒙受重大損害，經判定專利權不再具有經濟效益。試問某公司 X3 年此專利權之攤銷費用為何？",
