      "sessionId": "114Q3",
      "year": 114,
      "session": 3,
      "subject": "accounting",
      "sourceId": "accounting-05",
      "number": 14,
      "stem": "崎頂公司銷售的所有產品，皆提供一年期免費保固。根據以往的統計資料，約有 4%的產品可能需要維修，每件產品的平均維修費為 $60。X9年度共售出 200,000 件產品，實際支付維修費用為 $900,000，其中$600,000屬於X8年度銷售商品的保固支出。若公司在X8年底的財報中，已提列保固負債$600,000，請問：X9年底應認列的保固負債金額為多少？",
