      "sessionId": "114Q3",
      "year": 114,
      "session": 3,
      "subject": "accounting",
      "sourceId": "accounting-10",
      "number": 17,
      "stem": "外埔公司X3年度綜合損益表相關項目如下：營業收入$5,000,000，營業成本$3,375,000，推銷費用$450,000，管理費用$175,000，不動產、廠房及設備的重估增值 $200,000，國外營運機構財務報表換算之兌換利益$225,000，透過其他綜合損益按公允價值衡量之債務工具投資未實現評價損失 $75,000 。若所得稅率為 20%，請問：外埔公司 X3年度的綜合損益總額為多少？",
