      "sessionId": "114Q3",
      "year": 114,
      "session": 3,
      "subject": "accounting",
      "sourceId": "accounting-10",
      "number": 19,
      "stem": "大雅公司於X1年底透過公開競標，取得客戶甲公司之A產品廣告專案。為了成功取得該合約，該公司於X1年支出以下費用：A產品市場調查費用$1,900,000、提案資料印製費用$200,000，以及支付給介紹人的佣金$300,000。假設上述支出預期可於X2年合約履行完成後，自合約對價中回收，請問：這些成本對大雅公司X1年度淨利的影響金額為何？（不考慮所得稅）",
