      "sessionId": "114Q3",
      "year": 114,
      "session": 3,
      "subject": "accounting",
      "sourceId": "accounting-10",
      "number": 21,
      "stem": "南屯公司擁有長期資金總額$1,750,000，其中 40%為長期負債（利率 10%），其餘為普通股股東權益。假設該公司營業外收支僅包括利息費用，所得稅率為 20%，且公司希望達到 14% 的權益報酬率（ROE），請問：其營業淨利應為多少？",
