      "sessionId": "114Q3",
      "year": 114,
      "session": 3,
      "subject": "accounting",
      "sourceId": "accounting-17",
      "number": 24,
      "stem": "烏日公司向母公司買設備，結果支付的價格比公允價值還高，這樣的交易最有可能造成什麼結果？",
